/*
 * SELF-DESTRUCTING SERVICE WORKER
 *
 * This file used to be generated by next-pwa. The PWA was removed on
 * 2026-09-12, but every browser that ever visited the site still has the old
 * worker registered and would keep serving its cached copy of the site
 * indefinitely — deleting this file would NOT release them, because a 404 does
 * not reliably unregister an installed worker.
 *
 * So this replacement claims the registration, unregisters itself, drops every
 * cache it created, and reloads open tabs onto the live site.
 *
 * Safe to delete once traffic has cycled through at least one visit — roughly a
 * release or two. Until then, keep it deployed.
 */
self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      try {
        await self.registration.unregister();

        const cacheKeys = await caches.keys();
        await Promise.all(cacheKeys.map((key) => caches.delete(key)));

        // Reload any open tab so it stops being served by this worker.
        const clients = await self.clients.matchAll({ type: "window" });
        for (const client of clients) {
          client.navigate(client.url);
        }
      } catch {
        // Never let cleanup failure wedge the page.
      }
    })(),
  );
});
